INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(13000, 0, 130, 0, 0, 0, 'Silverpine Forest', 'Silverpine Forest runs along the rugged western coast of Lordaeron, a country of tall silver-barked pines between Tirisfal Glades to the north and the Greymane Wall to the south, with Lordamere Lake along its eastern edge. Beyond the wall lies Gilneas, the kingdom King Genn Greymane sealed away from the troubles of Lordaeron. Then came the Scourge, and with it Arugal, the archmage who summoned the worgen to fight the undead. The beasts turned on the living as well, and from Shadowfang Keep above Pyrewood Village the mad wizard now calls them his children. Lady Sylvanas counts Silverpine a strategic stronghold, and from an old crypt called the Sepulcher her Forsaken struggle to hold it. Enemies press them on every side: Moonrage worgen in the woods, rot hide gnolls and undead who bear the Ravenclaw name on the farms and Fenris Isle, and wizards of Dalaran at work in Ambermill. Refugees still huddle at the closed gates of the wall.', 'warcraft.wiki.gg/wiki/Silverpine_Forest (geography, Greymane Wall, Arugal and the worgen, Shadowfang above Pyrewood); quest 421 description (Varimathras, Arugal''s reckless magic, strategic stronghold); quest 1014 description; quest 1476 description (refugees refused at the Greymane Wall); quest_greeting 1952; DB spawns: Moonrage, Rot Hide, Ravenclaw, Dalaran creatures across the zone'),
(13001, 1, 130, 1, 0, 0, 'The Skittering Dark', 'Northwest of the Sepulcher lies the Skittering Dark, a gloomy corner of the forest given over to giant spiders. Moss stalkers and mist creepers spin their webs among the trees, and great grizzled bears wander the slopes around them. Even here the Forsaken see opportunity. Apothecary Renferrel of the Royal Apothecary Society has found that the blood of these spiders, mixed with a toxin drawn from the heart of a grizzled bear, yields a deadly elixir, one more ingredient in the New Plague the Dark Lady demands of his order.', 'quest 447 description (spiders in the Skittering Dark to the northwest, spider blood plus bear heart toxin); DB spawns in area 226: Moss Stalker 1780, Mist Creeper 1781, Giant Grizzled Bear 1797; quest_greeting 1937'),
(13002, 1, 130, 2, 0, 0, 'North Tide''s Run', 'North Tide''s Run is a lonely stretch of Silverpine''s sea coast, west of the Sepulcher, where the tide breaks against Lordaeron''s western shore. On it stands a shaman''s shrine whose pool has been tainted by the plague. The water spirits that once spoke there have fallen silent or been twisted into corrupt manifestations, and shamans of the Horde come to defeat the foul spirit and cleanse the pool with a ritual at the brazier beside it. Even when the corruption ebbs, they say, life in this forest goes on waning.', 'quest 63 description (shrine on the coast west of the Sepulcher, tainted by the plague); quest 100 description and reward text; quest 1103 (Tiev Mordune); DB spawns in area 305: Corrupt Water Spirit 5897, Corrupt Minor Manifestation of Water 5894, Shaman Shrine 101750, Brazier of Everfount 113791, Tiev Mordune 7007'),
(13003, 1, 130, 3, 0, 0, 'Malden''s Orchard', 'Malden''s Orchard is a farmstead in northern Silverpine, east of the Ivar Patch, and whoever once lived there is gone. Worgs now prowl its untended trees in such hungry numbers that the Deathstalker Erland, a Forsaken scout, found himself trapped in the farmhouse, eyed by the wolves every time he set foot outside the door. Among the pack roams a rarely seen worg called Gorefang. By Erland''s own count there are masses of wolves to the east, and of the orchard''s people no trace at all.', 'creature_text 1978 (Erland: masses of wolves to the east, whoever lived at Malden''s Orchard is gone); quest 435 description; quest 429 description (worgs between the Ivar Patch and Malden''s Orchard to the east); DB spawns in area 238: Mottled Worg 1766, Worg 1765, Gorefang 12431 (rare), Deathstalker Erland 1978'),
(13004, 1, 130, 4, 0, 0, 'The Ivar Patch', 'The Ivar Patch is a farm in northern Silverpine, north of the Sepulcher, where shambling Ravenclaw slaves, ghouls of the Scourge, now wander the fields. Its barn is the lair of Ivar the Foul, a ghoul who fell on the Deathstalkers Rane and Quinn Yorick when they passed through on a scouting mission and mauled Quinn badly. The brother and sister now hold out in the farmhouse, Rane standing guard while Quinn recovers, and Ivar lurks in the barn waiting for her watch to slip.', 'quest 425 description (attacked by Ivar the Foul, barn yonder); quest 430 log description (Ivar Patch north of the Sepulcher); quest_greeting 1950 (holed up in this farmhouse); warcraft.wiki.gg/wiki/Olsen''s_Farthing (Ravenclaw Slaves are ghouls under Thule); DB spawns in area 239: Ravenclaw Slave 1866 x15, Ivar the Foul 1971, Rane 1950, Quinn 1951'),
(13005, 1, 130, 5, 0, 0, 'The Dead Field', 'The Dead Field is a deserted farm in northern Silverpine whose former owners are unknown. The rot hide gnolls, servants of the Scourge, have made it a base, and every small assault the Forsaken have sent against it has been broken by the banshee Nightlash, who appears to defend the gnolls whenever they come under attack. At times a Ravenclaw apparition rises among them to stir their rage, calling the gnolls its creations and promising that the Dark Lady''s followers will be driven from Silverpine and the war carried to their very capital.', 'quest 437 description; warcraft.wiki.gg/wiki/The_Dead_Field (run-down deserted farm, nothing known of its owners, Ravenclaw Apparition); creature_text 2056 (Ravenclaw Apparition); smart_scripts areatrigger 173 summons Ravenclaw Apparition 2056 at the Dead Fields; DB spawns in area 240: Rot Hide Gladerunner 1772, Rot Hide Mystic 1773, Nightlash 1983'),
(13006, 1, 130, 6, 0, 0, 'Valgan''s Field', 'Valgan''s Field is a small wheat farm on the western shore of Lordamere Lake, north of a bridge on the forest road. When the archmage Arugal first came to Silverpine he stayed here, and he left behind a stack of dusty spellbooks, among them the spell he named his Remedy. Moonrage worgen, the cursed fruit of his magic, now prowl the farm, and Vile Fin murlocs creep up from the shore.', 'quest 422 description (Arugal first stayed at the wheat farm just north of the bridge, spellbooks, Remedy of Arugal); quest 13634 description and reward text (small farm on the western shore of Lordamere Lake, Black Knight''s story a sham); warcraft.wiki.gg/wiki/Valgan''s_Field; DB spawns in area 227: Moonrage Whitescalp, Moonrage Darkrunner, Vile Fin Shredder, Dusty Spellbooks 1571, Dusty Journal 194340'),
(13007, 1, 130, 7, 0, 0, 'The Sepulcher', 'Built into an old crypt and graveyard beside the road that crosses the forest, the Sepulcher is the Forsaken base in Silverpine and one of its few safe havens. High Executor Hadrec commands here and bats fly daily to the Undercity. Allies have come as well, among them the tauren Mura Runetotem, who hopes to bring new life to this dying forest. In the graveyard lies the tomb of a paladin named Yuriv, its fine epitaph praising him as father, husband and a servant of the Light whose devotion was unquestionable, crudely scratched over with the word BETRAYER.', 'warcraft.wiki.gg/wiki/The_Sepulcher (old crypt converted into the Forsaken base, one of the few safe Horde locations, leader Hadrec); quest 6322 reward text (our bats fly there daily); quest 9189 description (Advisor Sorrelon represents the blood elves to the Forsaken); quest 3301 description (Mura Runetotem); page_text 690 (Yuriv''s Tombstone); quest 264 description and reward text; DB spawns in area 228: Hadrec 1952, Silverpine Deathguard 7489, Karos Razok 2226, Advisor Sorrelon 16288, Mura Runetotem 8385, Yuriv''s Tombstone 24776/24777; page_text 690 (epitaph wording)'),
(13008, 1, 130, 8, 0, 0, 'Deep Elem Mine', 'Deep Elem Mine is cut into the hills southeast of the Sepulcher. Arugal let his magic spread even here, and the mine''s own former foreman, Grimson the Pale, now leads the worgen that have made its tunnels their home. Moonrage gluttons and darksouls crowd the shafts, still bound by the enchanted shackles through which Arugal strengthened his spells. The Forsaken covet the place. Dalar Dawnweaver reckons the mine would richly supply Varimathras''s advance across Silverpine, if only Grimson were dead.', 'quest 424 description and reward text (magic spread to the Deep Elem Mine in the hills to the southeast, tainted foreman Grimson the Pale); quest 423 description (shackles from Moonrage Gluttons and Darksouls); warcraft.wiki.gg/wiki/Deep_Elem_Mine (former foreman led the worgen who made the mine their home); DB spawns in area 213: Moonrage Glutton 1779, Moonrage Darksoul 1782'),
(13009, 1, 130, 9, 0, 0, 'The Decrepit Ferry', 'On the shore of Lordamere Lake east of the Sepulcher, the Decrepit Ferry is an old landing that the Scourge have made their own. Hands of Ravenclaw and Ravenclaw champions guard it alongside rot hide gnolls, and a boat tied up there is heaped with wrapped corpses. Why the Scourge hold so small a landing in such strength the Forsaken have yet to learn. Deathstalker reports also place Fenwick Thatros, named in a missive from Lord Varimathras as a leader of the undead in Silverpine, near the old dock.', 'quest 438 description and reward text; quest 439 description and reward text (body likely from the mass graves in Tirisfal); quest 1998 description (Fenwick Thatros near the decrepit dock on Lordamere); warcraft.wiki.gg/wiki/Fenris_Isle (Thule controls the Decrepit Ferry); DB spawns in area 237: Hand of Ravenclaw 1870, Ravenclaw Champion 1869, Corpse Laden Boat 1593; Fenwick Thatros 6570 just offshore; quest 438 description (heavily patrolled by rot hides and other undead)'),
(13010, 1, 130, 10, 0, 0, 'Fenris Isle', 'Fenris Isle rises from Lordamere Lake east of the Decrepit Ferry, crowned by Fenris Keep, once a thriving military outpost of the kingdom of Lordaeron. Its people fled or died when the Scourge came. Now the rot hide gnolls hold it, brutes, savages and plague weavers swarming its shores and halls, and the Forsaken name it the Scourge''s place of strength in Silverpine.', 'warcraft.wiki.gg/wiki/Fenris_Isle (thriving military outpost of Lordaeron, abandoned when the Scourge came, Rot Hide base under Thule); quest 442 description (the Scourge''s place of strength in Silverpine); quest 443 description (Fenris Isle east of the Decrepit Ferry); quest 460 description (Alaric, grave near the stable); DB spawns in area 172: Rot Hide Brute 1939, Plague Weaver 1940, Savage 1942, Thule Ravenclaw 1947, Shallow Grave 1599'),
(13011, 1, 130, 11, 0, 0, 'The Dawning Isles', 'The Dawning Isles are a scatter of small islands out in Lordamere Lake, east of Fenris Isle. Vile Fin murlocs, tidecallers and shorecreepers among them, crowd their shores, and mossy lake creepers lumber through the shallows. The lake holds an old secret. Ages ago an ancient plague killed off all the aquatic life in Lordamere, and the Royal Apothecary Society''s Apothecary Berard was studying it when Arugal''s curse took his mind.', 'quest 450 description (ancient plague killed off all aquatic life in Lake Lordamere ages ago); quest 451 description (Lake Creeper and Skulker moss, Hardened Tumor from a Vile Fin, islands in Lake Lordamere); DB spawns in area 232: Vile Fin Tidecaller 1958, Vile Fin Shorecreeper 1957, Lake Creeper 1955, Elder Lake Creeper 1956'),
(13012, 1, 130, 12, 0, 0, 'Olsen''s Farthing', 'South of the Sepulcher lie the ruins of Olsen''s Farthing, once a bustling farmstead on a major trade route through the forest. A few years after the Third War it fell to undead of the Scourge who bear the Ravenclaw name, and it has never recovered. Skeletal Ravenclaw raiders patrol the broken fences and ghoulish Ravenclaw slaves shamble among the empty buildings, ready to fall on anyone who strays too near.', 'warcraft.wiki.gg/wiki/Olsen''s_Farthing (bustling farmstead on a major trade route, ruined and overrun by Thule''s undead a few years after the Third War, Raiders are skeletal warriors, Slaves are ghouls); DB spawns in area 229: Ravenclaw Raider 1865 x11, Ravenclaw Slave 1866 x10 (average position south of the Sepulcher)'),
(13013, 1, 130, 13, 0, 0, 'Pyrewood Village', 'Pyrewood Village lies in southern Silverpine beneath Shadowfang Keep, a village of chapel, smithy and town hall not far north of the Greymane Wall. Arugal''s curse has given it two faces. By day its folk seem ordinary, keeping shop and standing watch; when the sun goes down they become Moonrage worgen, held by enchanted shackles. Arugal rules them through the Pyrewood Council, puppets led by Lord Mayor Morrison. Apothecary Berard kept his study at the inn before the curse took him.', 'warcraft.wiki.gg/wiki/Pyrewood_Village (town hall, blacksmith, chapel, Lord Mayor Morrison leads the council, worgen at night); quest 99 description (human by day, Moonrage worgen at night, enchanted shackles); quest 452 description (Council as puppets); quest 450 description (Berard''s study in the Pyrewood Village Inn); creature_text 27619 (Rise, Arugal) and 27624 (sent to Solstice Village); DB spawns: Shade of Arugal 27620 and San''layn princes in area 204; Pyrewood Armorer/Tailor/Leatherworker vendors; warcraft.wiki.gg/wiki/Archmage_Arugal (San''layn raise Arugal for the Grizzly Hills); DB spawns in area 204 (posarea): Prince Valanar 27619, Prince Atherann 27616, Shade of Arugal 27620; Keleseth 27618 and Theraldis 27624 just outside'),
(13014, 1, 130, 14, 0, 0, 'Ambermill', 'Ambermill, in southeastern Silverpine near Lordamere Lake, was a minor lumber town of mills and stables. After the Third War wizards of the Kirin Tor occupied it, guarded by warders and protectors, with the archmage Ataeric among them, and supplied by crates carted up from Hillsbrad. What draws Dalaran to so small a town is not plain to see. To the Forsaken it is a stubborn source of human opposition, and a vault of Dalaran''s secrets.', 'warcraft.wiki.gg/wiki/Ambermill (town hall, stables, mills, lumber; Kirin Tor occupied after the Third War; dormant ley node); quests 477, 482, 480 descriptions; quest 1999 description (Kirin Tor at Ambermill store documents on the state of Dalaran); DB spawns in area 233: Dalaran Warder 1913, Protector 1912, Archmage Ataeric 2120 (drops Ataeric''s Staff 3515 for quest 480); wowhead.com/classic/npc=2120 (Archmage Ataeric exists in Classic, Silverpine Forest)'),
(13015, 1, 130, 15, 0, 0, 'Beren''s Peril', 'Beren''s Peril is a cave in the hills southwest of Ambermill, not far from a pocket of Dalaran wizards. Forsaken scouts have learned that a band of undead is hiding inside: Ravenclaw guardians and drudgers of the Scourge, gathering in secret to strike at the Sepulcher. Among them lurks a rarely seen Ravenclaw Regent. Shadow Priest Allister means to turn the tables and fall on them before they are ready.', 'quest 516 description; warcraft.wiki.gg/wiki/Beren''s_Peril (cave southwest of Ambermill, undead servants of Thule preparing an attack on the Sepulcher); DB spawns in area 231: Ravenclaw Guardian 1973, Ravenclaw Drudger 1974, Dalaran Watcher 1888; Ravenclaw Regent 2283 (rare) nearby'),
(13016, 1, 130, 16, 0, 0, 'The Greymane Wall', 'The Greymane Wall closes off the south of Silverpine, the great barrier King Genn Greymane raised to shut Gilneas away from the troubles of Lordaeron. Its gates stay shut against all who come to them, and no help comes from the other side. Refugees from fallen Lordaeron camp in its shadow, haggard and sickly, refused by their own kin. Dalin Forgewright tends them, the blind weaponsmith Wallace sells his blades nearby, and a man named Valdred Moray lingers near the gate.', 'warcraft.wiki.gg/wiki/Greymane_Wall (built by Genn to seal Gilneas off, refugees, Dalin, Valdred, Wallace; the gate opening and worgen lines are cited to Chronicle 3 and Curse of the Worgen, not used); quest 1476 description (Dalin Forgewright cares for the refugees refused by their kin); quest 530 description (Valdred at the Greymane Wall trying to flee into Gilneas); DB spawns in area 230: Haggard Refugee 2053, Sickly Refugee 2054, Dalin Forgewright 5682, Wallace the Blind 3534, Valdred Moray 2332; warcraft.wiki.gg/wiki/Greymane_Wall In the RPG (Lands of Conflict: gates unmanned, refugees camp in its shadow and never meet a Gilnean)'),
(13017, 2, 130, 1, 2, 0, 'High Executor Hadrec', 'High Executor Hadrec commands the Forsaken at the Sepulcher, and he greets every newcomer with the same blunt truth: Silverpine is saturated with enemies, and if the Forsaken are to survive they must drive them back. From his post he sends searchers after the Deathstalkers lost among the northern farms and orders the assaults on the rot hide gnolls at the Dead Field, where the banshee Nightlash has broken every small attack so far. Even the armory has his attention, and he has the Deathguards'' lost weapons replaced from the Undercity.', 'quest_greeting 1952; quests 428, 437, 442 descriptions; quest 6321 description (Hadrec asked for stock of equipment); quest 449 reward text (had not accounted for the level of Scourge presence); quest 437 description'),
(13018, 2, 130, 2, 2, 0, 'Dalar Dawnweaver', 'Dalar Dawnweaver was an archmage of the Kirin Tor before the Scourge, and now serves the Dark Lady at the Sepulcher. He holds Arugal in open contempt: a charlatan whose spellcraft was as transparent as blown glass, who propped up weak magic with enchanted trinkets and was never fit to represent Dalaran in its darkest hour. Dalar insists he warned the Kirin Tor and was ignored. Now he studies Arugal''s spells and shackles so he can turn them against their maker and secure Silverpine for Sylvanas. He knows his old order''s secrets as well, and its ways of working magic.', 'warcraft.wiki.gg/wiki/Dalar_Dawnweaver (former archmage of the Kirin Tor); quest_greeting 1938 (Kirin Tor did not heed my warnings); quests 422, 423 descriptions; quest 481 reward text; quest 482 description'),
(13019, 2, 130, 3, 2, 0, 'Apothecary Renferrel', 'Apothecary Renferrel of the Royal Apothecary Society keeps his station outside the Sepulcher, where he labors on the task the Dark Lady has set his order: a New Plague to bring Arthas and his army to their knees, and the human infestation with them. He brews from whatever Silverpine offers, spider blood and the hearts of bears and worgs among them, and he can spare a healing draught for a wounded Deathstalker. He shares his findings with his colleagues of the Society, in the Undercity and as far away as Tarren Mill.', 'quest_greeting 1937; quest 447 description (New Plague, Scourge Army and the Human infestation); quests 450, 451; quests 429, 430 (healing potion from worg hearts); quest 443 description (stationed outside the Sepulcher); quest 444 description; quest 493 description'),
(13020, 2, 130, 4, 2, 0, 'Shadow Priest Allister', 'Shadow Priest Allister is the Sepulcher''s keeper of secrets. Through scouts and agents, he boasts, the Forsaken control the flow of information in Lordaeron, with every Scourge movement and holding under their watchful eyes. His chief concern is Ambermill, where the support of Dalaran''s wizards keeps human opposition alive, and he means to learn why they care for such a backwater by raiding the crates they ship from Hillsbrad. His scouts also report undead who bear the Ravenclaw name holing up at Beren''s Peril to strike at the Sepulcher, and he means to strike them first.', 'quest_greeting 2121; quests 477, 479, 480 descriptions and reward texts; quest 516 description and reward text'),
(13021, 2, 130, 5, 0, 0, 'Thule Ravenclaw', 'Thule Ravenclaw was a young mage of great promise in Dalaran before the war, a friend of Bethor Iceshard and Gunther Arcanus. When the Lich King rose, he betrayed his brethren and went over to the Scourge. Now he holds Fenris Keep and leads the rot hide gnolls, whose animating ichor he brewed with warlock and necromantic arts, along with the undead who bear his name. Through his apparitions he calls the gnolls his creations and promises them a war carried to the Forsaken capital itself.', 'quest 446 description (young promising mage, betrayed his brethren, allied with the Scourge); quest 491 description and reward text (Woven Wand); quest 444 description; creature_text 2056 (bring the tides of war to their very capital); warcraft.wiki.gg/wiki/Thule_Ravenclaw; codex_tirisfal.json Gunther Arcanus entry; warcraft.wiki.gg/wiki/Olsen''s_Farthing (Ravenclaw undead serve Thule)'),
(13022, 2, 130, 6, 2, 0, 'Rane and Quinn Yorick', 'Rane and Quinn Yorick are Deathstalkers, sister and brother, sent to scout the farms of northern Silverpine and report to High Executor Hadrec. Weeks have passed without word. Their mission foundered at the Ivar Patch, where the ghoul Ivar the Foul fell on them and mauled Quinn badly. The pair escaped into the farmhouse, and Rane stands guard, watching for Ivar''s return while her brother heals. A third member of their team, Erland, has not rejoined them, and Rane fears the dangers of Silverpine have overcome him.', 'quest 428 description (a couple of weeks without word); quest 425 description; quest 429 description; quest 430 completion text (my sister); quest_greeting 1950; quest 435 description (my teammate Rane); quest 449 description; creature_text 1950, 1951'),
(13023, 2, 130, 7, 2, 0, 'Alaric', 'Alaric was once head servant and bodyguard to Thule Ravenclaw in Fenris Keep. When the plague came, his master cast a spell meant to protect him from undeath, and instead bound him to an unlife from which he cannot escape. After creating the rot hide gnolls, Thule cut off Alaric''s head and gave it to the gnolls as a plaything, and they carry the talking head about Fenris Isle still. Alaric asks only to be reunited with his body, which he believes the gnolls buried in an unmarked grave near the keep''s stable.', 'quest 460 description and completion text; quest 461 description and reward text; quest 491 description; item 3317 A Talking Head drops from Rot Hide gnolls on Fenris Isle (Horde only, conditions team 67)'),
(13024, 2, 130, 8, 0, 0, 'Nightlash', 'Nightlash is a banshee of the Scourge who haunts the Dead Field in northern Silverpine. She guards the rot hide gnolls, servants of the Scourge, who make their base on the old farm, and each time the Forsaken have sent a small force against it she has appeared at the gnolls'' side and used her magic to rout the attackers. High Executor Hadrec wants her destroyed, for the Forsaken cannot break the rot hides while she defends them, and he knows she shows herself only when the gnolls are hard pressed. When she falls, he says, her essence will turn to dust.', 'quest 437 description and reward text; warcraft.wiki.gg/wiki/The_Dead_Field; DB spawn Nightlash 1983 at the Dead Field, faction template 70 (hostile to all)'),
(13025, 3, 130, 1, 2, 0, 'Arugal''s Folly', 'To Dalar Dawnweaver, the curse on Silverpine is the work of one fool. Lady Sylvanas, he says, has charged Varimathras with conquering the lands to the south, and Arugal, charlatan of Dalaran and now cursed beast of Shadowfang Keep, has let his reckless magic wreak havoc on this strategic stronghold. Dalar tests newcomers against the Moonrage worgen below the Sepulcher, then sets out to learn exactly what magic Arugal used so he can turn it against him, starting with the spell Arugal called his Remedy, left among his spellbooks at Valgan''s Field. In Pyrewood, the Deathstalker Faerleia lies in wait for the Pyrewood Council, Arugal''s puppets, hoping his creatures will turn on him once they are gone. And Arugal still resides in the keep: until he is slain, the Dark Lady cannot claim Silverpine.', 'quests 421, 422, 423, 424, 99 (descriptions and reward texts); quest 452 description and reward text; quest 1014 description; creature_queststarter: 1938 starts 421-424, 99, 1014; 2058 starts 452'),
(13026, 3, 130, 2, 2, 0, 'The Lost Deathstalkers', 'Weeks ago two Deathstalkers, Rane and Quinn Yorick, were sent through northern Silverpine to scout its farms and report to High Executor Hadrec. Nothing has been heard from them since. They may have fallen to the Scourge, and if so Hadrec wants it confirmed, so he sends searchers among the northern farms where their mission began. The pair were not alone out there: a third Deathstalker, Erland, was part of their team, and the farms of the north are thick with ghouls, gnolls and hungry wolves.', 'quests 428, 429, 430, 425, 435, 449 (descriptions and reward texts); quests 3221, 1359, 1358 descriptions; creature_text 1978'),
(13027, 3, 130, 3, 2, 0, 'The Ravenclaw Menace', 'The rot hide gnolls, servants of the Scourge, trouble the Forsaken from an old farm north of the Sepulcher called the Dead Field. Every small assault High Executor Hadrec has sent against them has been routed by the banshee Nightlash, who appears to defend the gnolls whenever they come under attack, and he wants her destroyed. Who commands the rot hides, and to what end, the Forsaken have yet to learn. Meanwhile Shadow Priest Allister''s scouts report undead holing up in a cave called Beren''s Peril, near a pocket of Dalaran wizards, to prepare an attack on the Sepulcher, and he means to strike them first.', 'quests 437, 438, 443, 444, 446, 448, 442 (descriptions and reward texts); creature_text 1498; quest 516 description; Tirisfal writer: graverobbers trail (444, 446) continues from codex_tirisfal.json The Graverobbers'),
(13028, 3, 130, 4, 2, 0, 'Deliah''s Ring', 'Among the corpses heaped in the boat at the Decrepit Ferry, the dead bound across Lordamere Lake for Fenris Isle, one hand lies unwrapped. It is a woman''s, pocked by plague but relatively fresh, and on it is a ring. Removed and turned to the light, it shows an engraving: For Deliah. Whoever she was, she died not long ago, and someone once loved her enough to give her the ring. High Executor Hadrec at the Sepulcher will want to see it, and it may yet lead to whoever that was.', 'quests 439, 440, 441, 530 (descriptions and reward texts); creature_template 2050 subname Ex-Chef; gameobject_queststarter 1593 starts 439; quest 440 reward text (Sevren)'),
(13029, 3, 130, 5, 2, 0, 'Dalaran''s Intentions', 'The Forsaken cannot see why the wizards of Dalaran care about a backwater like Ambermill, a town that remains a source of human opposition thanks to their support. Shadow Priest Allister suspects it must hold some greater importance. The wizards have been shipping crates by the wagon from Hillsbrad, and many of those supplies end up at a small camp north of Pyrewood Village. Allister wants the contents of one of those crates, in the hope that they will show at last what Dalaran intends for the town.', 'quests 477, 478, 481, 482, 479, 480 (descriptions and reward texts); DB: Archmage Ataeric 2120 drops Ataeric''s Staff 3515, quest 480 required item; gameobject 1627 Dalaran Crate at the camp north of Pyrewood'),
(13030, 3, 130, 6, 2, 0, 'A Recipe for Death', 'The Royal Apothecary Society labors under heavy pressure from the Dark Lady to produce a New Plague, one that could wipe out both the Scourge and the humans of Lordaeron. Apothecary Renferrel believes Silverpine holds the ingredients, and he shares what he learns with his colleagues of the Society as far away as Tarren Mill. His studies show that spider blood from the Skittering Dark, mixed with toxin from the hearts of grizzled bears, yields a deadly elixir, and samples of both are wanted by Master Apothecary Faranell in the Undercity.', 'quests 447, 450, 451 (descriptions and reward texts); quest 493 description; quest_greeting 2055');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(13006, 1, 13, 255, 'Far to the north, at the Argent Tournament in Icecrown, a champion called the Black Knight claims to hail from Valgan''s Field. Dark rumors follow him, for every rider scheduled to face him in the lists has met an untimely end, and the tournament''s crusaders want his story looked into.', 'quest 13634 description'),
(13006, 2, 13, 255, 'Nothing at the farm bears out his tale. Word of what was found there persuades the crusaders that the Black Knight''s story is a sham, dishonorable at the least and murderous at the worst, and until they can tie him to the deaths they mean to watch him quietly rather than confront him.', 'quest 13634 reward text'),
(13007, 1, 8, 255, 'Since the blood elves joined the Horde, Silvermoon keeps an envoy here as well. Advisor Sorrelon represents the sin''dorei to the Forsaken and offers his counsel to the High Executor, confident that together they can forge the Horde into something stronger than before and turn back the Scourge.', 'quest 9189 description (Advisor Sorrelon represents us to the Forsaken there); npc_text 8462 (gossip menu 7183)'),
(13007, 2, 0, 255, 'Yuriv''s widow has not forgiven him. Left waiting night after night while he put his crusade before her and their children, she has sent a pendant back to lie upon his tomb, wanting nothing more to do with it or with him. Laid on the carved stone, its gem grows dull.', 'quest 264 description and reward text (turned in at Yuriv''s Tombstone 24776)'),
(13009, 1, 0, 255, 'The corpses are bound across the water. Looking east over Lordamere Lake from the boat, a matching dock can be seen on Fenris Isle, and it is there that the fate of the dead must lie.', 'quest 438 reward text'),
(13009, 2, 0, 255, 'One body among them is a woman''s, pocked by plague yet recently dead. High Executor Hadrec reasons that so fresh a corpse can only have come from the mass graves of Tirisfal: the rot hide gnolls are robbing those graves and ferrying the dead to Fenris Isle.', 'quest 439 description and reward text'),
(13010, 1, 0, 255, 'The island has a master. Within Fenris Keep, guarded by the rot hide gnolls who swarm its shores and halls, dwells Thule Ravenclaw, who has made the old military outpost his stronghold and holds the island for the Scourge.', 'quest 446 reward text (Thule in his stronghold on Fenris Isle); DB spawn Thule Ravenclaw 1947 in Fenris Keep among the Rot Hides'),
(13010, 2, 0, 255, 'The gnolls keep a grisly plaything: the talking head of Alaric, once head servant and bodyguard to Thule Ravenclaw, cut off by his own master and given to them. Alaric believes the gnolls buried his headless body in an unmarked grave near the keep''s stable.', 'quest 460 description'),
(13011, 1, 0, 255, 'Berard''s journal, recovered from his study in Pyrewood, points to the islands themselves. The moss that grows on the lake''s skulkers and creepers, and a very rare hardened tumor he once found on a Vile Fin murloc, may yet hold the key to brewing another plague.', 'quest 450 reward text; quest 451 description'),
(13013, 1, 13, 255, 'A vision of the past shows what became of Arugal after his death. Princes of the San''layn, servants of the Lich King, came to Pyrewood and raised his shade in their master''s name. He would suit their needs perfectly, they said, and was to be sent north to Solstice Village in the Grizzly Hills, for Arthas would not be pleased if they fell behind schedule.', 'creature_text 27619 (Rise, Arugal) and 27624 (sent to Solstice Village, Arthas will not be pleased); quest 12327 Out of Body Experience (Ruuna the Blind, Grizzly Hills, neutral): description, reward text (Solstice Village); smart_scripts 2762000 casts its quest credit; creature_template_addon aura 49130 on 27616/27618/27619/27620/27624: the scene is seen only in the quest''s vision'),
(13014, 1, 0, 255, 'The reason lies beneath the town. Ambermill sits on a dormant ley energy node that the Kirin Tor earmarked long ago, and the wizards are weaving their magic to wake it and turn its energies to some greater purpose.', 'quest 482 description (offered by Dalar on the turn-in of 481)'),
(13016, 1, 0, 255, 'Valdred is no simple refugee. He murdered Deliah of Brill, the wife of his good friend Raleigh, and has come to the wall hoping to flee into Gilneas. Raleigh, now one of the Forsaken in the Undercity, has not forgotten, and wants him dead.', 'quest 530 description'),
(13017, 1, 0, 255, 'The Deathstalkers'' report, when it reaches him at last, shakes his confidence. He admits he had not reckoned on so strong a Scourge presence in Silverpine, nor on the troubles his scouts have met, and he makes sure those who helped them are commended.', 'quest 449 reward text'),
(13017, 2, 0, 255, 'When Bethor Iceshard names Thule Ravenclaw as the power behind the rot hides, Hadrec wastes no time. Such a foe must be dealt with soon, he declares. He opens the Sepulcher''s arsenal to those who will go, and orders the assault on Fenris Isle, the Scourge''s place of strength in Silverpine, demanding Thule''s head.', 'quest 448 reward text; quest 442 description'),
(13018, 1, 0, 255, 'His knowledge of the Kirin Tor proves its worth at Ambermill. Shown a rune-inscribed pendant from a Dalaran crate, he knows it for an artifact his old order uses to channel great energies, and then remembers what he had forgotten: Ambermill sits on a dormant ley node the Kirin Tor once earmarked, and the wizards mean to wake it.', 'quest 481 reward text; quest 482 description'),
(13019, 1, 0, 255, 'When the rot hide gnolls appear, Renferrel reduces the ichor that flows through their bodies to its base components. His findings are not conclusive, but they show that warlock and necromantic magic went into its making, and he sends a sample to Bethor Iceshard in the Undercity, whose knowledge of magic runs deeper than his own.', 'quest 444 description (offered on the turn-in of 443)'),
(13019, 2, 0, 255, 'Bethor''s answer comes back as a scroll of incantations against the spells of Thule Ravenclaw. Renferrel has never worked such forces into a potion, and from it he brews a powerful mixture for those who would attack Thule in his stronghold on Fenris Isle.', 'quest 446 reward text'),
(13020, 1, 0, 255, 'Once Dalar Dawnweaver learns that the wizards mean to wake a ley node beneath Ambermill, Allister has the pendants that channel their magic stripped from conjurers, mages and protectors. It is not enough. The weaving is already far along, guided by an archmage of great power, and Allister orders him slain.', 'quest 479 description and reward text; quest 480 description'),
(13020, 2, 0, 255, 'The archmage falls, and with him the wizards'' magic: the ley energies fade back into dormancy. Allister counts it a major blow against the overbearing wizards of Dalaran, yet warns that so great a source of power lying so close at hand demands plans for the future.', 'quest 480 reward text'),
(13021, 1, 0, 255, 'Thule Ravenclaw meets his end at last in Fenris Keep, the stronghold from which he sent out his gnolls and his undead. The young mage of Dalaran who once showed such promise, and who chose the Scourge over his brethren, is destroyed.', 'KILL 1947 in Fenris Keep; quest 442 description and reward text'),
(13021, 2, 0, 255, 'Long ago Thule and his two friends wove their apprentice wands together into a single Woven Wand, a token of their friendship. Thule came to despise it, yet he could neither part with it nor let the others have it, so he stole it and hid it in Fenris Keep.', 'quest 491 description'),
(13022, 1, 0, 255, 'Ivar the Foul is hunted down in his barn and slain, and with a potion that Apothecary Renferrel brews from discolored worg hearts, Quinn feels his wounds begin to mend. Rane promises to name those who helped in the report she makes to her superiors.', 'quest 425 reward text; quest 430 reward text'),
(13022, 2, 0, 255, 'Erland turns up alive after all, escorted back through the wolves of Malden''s Orchard, where they had kept him trapped in the farmhouse. With the team together again, Rane sends their report on to Hadrec at once, for it holds information vital to the Forsaken hold on Silverpine.', 'quest 435 description and reward text; quest 449 description; creature_text 1950, 1978'),
(13023, 1, 0, 255, 'His body lies where he hoped, in a hastily dug grave, and Alaric is glad the gnolls did not destroy it. Now he asks to be carried to a hidden niche behind a dusty shelf in the keep''s southwestern tower, which holds an item dear to Thule and his old colleagues.', 'quest 460 reward text; quest 461 description'),
(13023, 2, 0, 255, 'The niche opens, and Alaric asks to be left there, for he spent the best days of his life in this keep and takes comfort in resting within its walls. Inside lies the Woven Wand that Thule hid rather than part with, and Alaric sends it to Bethor Iceshard, one of Thule''s friends from years past.', 'quest 461 reward text; quest 491 description'),
(13024, 1, 0, 255, 'Nightlash appears at last when the rot hides are pressed hard enough, and is destroyed. Without the banshee at their side, the gnolls of the Dead Field have lost the guardian who broke every Forsaken assault against them.', 'quest 437 description and reward text; KILL 1983'),
(13025, 1, 0, 255, 'The Remedy confirms Dalar''s worst suspicions. Arugal, he sneers, was not fit to clean chamber pots in Dalaran, let alone represent the Kirin Tor in its darkest hour, and he propped up his weak magic with enchanted items. Dalar has the shackles of Moonrage gluttons and darksouls gathered so he can study them first hand.', 'quest 423 description (offered on the turn-in of 422)'),
(13025, 2, 0, 255, 'Arugal''s magic, the Deathstalkers find, has spread even to the Deep Elem Mine, whose tainted foreman Grimson the Pale leads the worgen there. While Dalar studies, Grimson is beheaded, and the mine passes to the Forsaken, a rich resource for their advance through Silverpine.', 'quest 424 description and reward text'),
(13025, 3, 0, 255, 'The last piece lies in Pyrewood, whose people seem human by day and become Moonrage worgen when the sun goes down, held by the enchanted shackles Arugal cast on them. With the energy drawn from those shackles Dalar''s knowledge is complete, and he vows that Arugal will fall and his reckless magic be undone.', 'quest 99 description and reward text'),
(13025, 4, 0, 255, 'The ambush succeeds. Faerleia and her ally cut down the Pyrewood Council as it returns, and she salutes a true disciple of the Dark Lady, hoping that without its puppet masters the town can at last be brought under control and Arugal driven from Shadowfang Keep.', 'quest 452 reward text; creature_text 2058'),
(13025, 5, 0, 255, 'At last Arugal is slain in Shadowfang Keep and his head laid before Dalar. Silverpine is finally free from the grip of that wretch, Dalar declares, and the Dark Lady has been done a great service, for with his death her hold on Lordaeron grows.', 'quest 1014 reward and completion text'),
(13026, 1, 0, 255, 'The searchers find them holed up in the farmhouse at the Ivar Patch. The ghoul Ivar the Foul fell on them there and mauled Quinn badly, and Rane, who is no apothecary, knows only that the Society can brew healing potions from the discolored hearts of worgs, which roam between the farm and Malden''s Orchard.', 'quest 428 reward text; quest 429 description'),
(13026, 2, 0, 255, 'Apothecary Renferrel brews the draught, remarking that he hopes such Deathstalker failures are rare, and Quinn drinks it and feels it working. Ivar the Foul is then hunted down in his barn and slain, so that Quinn has time to heal.', 'quest 429 and 430 reward texts; quest 425 description and reward text'),
(13026, 3, 0, 255, 'Erland, trapped by wolves in the farmhouse at Malden''s Orchard, is escorted back through the trees to his comrades, and the Deathstalkers'' report finally reaches the Sepulcher. Hadrec admits he had not reckoned on so strong a Scourge presence in Silverpine, nor on the troubles his scouts have met.', 'quest 435 description; quest 449 reward text'),
(13026, 4, 0, 255, 'The worg hearts prove interesting in their own right. Renferrel finds in them a toxicity that should be deadly to the very wolves in which they beat, a quality unseen in similar specimens, and he sends samples to his colleague Apothecary Zinge in the Undercity for further study.', 'quest 3221 reward text; quest 1359 description (offered on the turn-in of 3221)'),
(13027, 1, 0, 255, 'Nightlash falls, her essence crumbling to dust, and the Scourge lose ground. Soon the Forsaken find a new hive of theirs at the Decrepit Ferry east of the Sepulcher, heavily patrolled by rot hides and other undead, and Hadrec wants to know why they are there.', 'quest 437 reward text; quest 438 description'),
(13027, 2, 0, 255, 'At the ferry lies a boat heaped with wrapped corpses, and across Lordamere Lake an opposing dock can be seen on Fenris Isle. Whatever the Scourge want with the dead, the answer must lie out on the island.', 'quest 438 reward text'),
(13027, 3, 0, 255, 'Before striking the island, Hadrec means to learn who is behind the gnolls, and the ichor that flows in their bodies is gathered for the apothecaries. Renferrel finds warlock and necromantic magic in it, and in the Undercity Bethor Iceshard knows the work at once. It was crafted by his old colleague Thule Ravenclaw, a promising mage who betrayed his brethren for the Lich King. Bethor had not known that Thule still existed, nor that he led the rot hides, and he supplies incantations for a potion to counter Thule''s spells.', 'quest 443 description; quest 444 description and reward text; quest 446 description; creature_text 1498'),
(13027, 4, 0, 255, 'With Bethor''s potion and arms from Hadrec''s arsenal, the Forsaken strike Fenris Isle, the Scourge''s place of strength in Silverpine, and destroy Thule Ravenclaw. The energies released at his end are felt even at the Sepulcher, and the deed rings through the ranks of the Forsaken.', 'quest 448 reward text; quest 442 description and reward text'),
(13028, 1, 0, 255, 'Hadrec reasons that so fresh a body can only have come from the mass graves of Tirisfal, and doubts that whoever gave the ring still cares. In Brill, Magistrate Sevren''s records bear him out: a Deliah lived there not long ago and was laid in the mass grave, and the rot hides must have stolen her. Her husband, Raleigh, now dwells in the Undercity.', 'quest 439 reward text; quest 440 description and reward text; quest 441 description'),
(13028, 2, 0, 255, 'Raleigh, once a chef, knows the ring for his wife''s, yet feels nothing for her death or for the theft of her body. One desire still burns in his dead heart: revenge. Valdred Moray, once his good friend, was Deliah''s murderer, and has fled to the Greymane Wall hoping to slip into Gilneas. Raleigh wants him dead and his hands brought back.', 'quest 441 reward text; quest 530 description (offered on the turn-in of 441); creature_template 2050 subname Ex-Chef'),
(13028, 3, 0, 255, 'When Valdred''s hands are brought to him, Raleigh gives back the ring as a worthless bauble, for Deliah has been dead to him for a long time. The hands he keeps instead, as a remembrance of his friend''s betrayal.', 'quest 530 reward text'),
(13029, 1, 0, 255, 'Inside the crate lie old maps of Silverpine and western Lordaeron and a rune-inscribed pendant. Dalar Dawnweaver knows it at once as an artifact the Kirin Tor use to channel great energies, and so many of them mean a project of real magnitude. Then he remembers: Ambermill was earmarked by the Kirin Tor for its dormant ley energy node, and the wizards mean to wake it.', 'quests 477, 478, 481 reward texts; quest 482 description'),
(13029, 2, 0, 255, 'Allister orders the pendants stripped from Ambermill''s conjurers, mages and protectors to slow the weaving, but it is already far along, guided by an archmage of great power. Only his death can halt it now, though he is surely guarded by many mages and warders.', 'quest 479 reward text; quest 480 description'),
(13029, 3, 0, 255, 'Archmage Ataeric falls, and as the wizards'' magic dissipates the ley energies fade back into dormancy. It is a major blow to the overbearing wizards of Dalaran, yet Allister warns that such power so close at hand demands plans for the future.', 'quest 480 reward text; DB: Archmage Ataeric 2120 drops Ataeric''s Staff 3515, quest 480 required item'),
(13030, 1, 0, 255, 'Faranell begins studying the samples at once, and has a further task in mind. Apothecary Berard, one of the Society''s most promising members, was cursed by Arugal into a mindless servant, but his journal, left in his study at the Pyrewood inn, records his work on an ancient plague that killed all the aquatic life in Lordamere Lake ages ago.', 'quest 447 reward text; quest 450 description (offered by Faranell on the turn-in of 447)'),
(13030, 2, 0, 255, 'Berard''s journal points to the moss of the lake''s skulkers and creepers, and to a very rare hardened tumor he once found on a Vile Fin murloc, so rare that he only ever obtained one.', 'quest 450 reward text; quest 451 description'),
(13030, 3, 0, 255, 'When the moss and the tumor reach him, Faranell mourns the loss of Berard, yet declares that through Renferrel''s diligent research the cursed apothecary''s studies will still serve the Dark Lady. The Society, he says, is on the cusp of something great.', 'quest 451 reward text');
